import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"openshield status — Output Format","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/cli/status.md","filePath":"openshield-xdp/cli/status.md","lastUpdated":null}'),n={name:"openshield-xdp/cli/status.md"};function d(o,e,l,p,r,c){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="openshield-status-—-output-format" tabindex="-1"><code>openshield status</code> — Output Format <a class="header-anchor" href="#openshield-status-—-output-format" aria-label="Permalink to &quot;\`openshield status\` — Output Format&quot;">​</a></h1><p>The <code>status</code> command prints a human-readable snapshot of the current OpenShield-XDP state.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>Root is not required unless <code>/sys/fs/bpf</code> permissions are restricted.</p><h2 id="output-fields" tabindex="-1">Output fields <a class="header-anchor" href="#output-fields" aria-label="Permalink to &quot;Output fields&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpenShield-XDP Status</span></span>
<span class="line"><span>=====================</span></span>
<span class="line"><span>  XDP Program:  LOADED</span></span>
<span class="line"><span>  Loader:       RUNNING</span></span>
<span class="line"><span>  Telemetry:    AVAILABLE</span></span>
<span class="line"><span>  Interface:    eno1</span></span>
<span class="line"><span>  XDP Mode:     native</span></span>
<span class="line"><span>  Static Mit:   true</span></span>
<span class="line"><span>  Dynamic Mit:  true</span></span>
<span class="line"><span>  Whitelist:    true (3 IPs)</span></span>
<span class="line"><span>  Config:       PRESENT</span></span>
<span class="line"><span>  BPF Pin:      EXISTS</span></span>
<span class="line"><span>  Systemd:      INSTALLED</span></span></code></pre></div><h3 id="field-descriptions" tabindex="-1">Field descriptions <a class="header-anchor" href="#field-descriptions" aria-label="Permalink to &quot;Field descriptions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Source</th><th>Values</th></tr></thead><tbody><tr><td><strong>XDP Program</strong></td><td><code>bpf.IsLoaded()</code> — checks if <code>/sys/fs/bpf/</code> contains pinned maps</td><td><code>LOADED</code> (green) or <code>NOT LOADED</code> (red)</td></tr><tr><td><strong>Loader</strong></td><td>PID file at <code>/var/run/openshield/loader.pid</code> — checks if the process is alive and its cmdline contains &quot;openshield&quot;</td><td><code>RUNNING</code> (green) or <code>NOT RUNNING</code> (yellow)</td></tr><tr><td><strong>Telemetry</strong></td><td>Unix socket at <code>/var/run/openshield/telemetry.sock</code> — checks if file exists</td><td><code>AVAILABLE</code> (green) or <code>UNAVAILABLE</code> (red)</td></tr><tr><td><strong>Interface</strong></td><td>Config file <code>interface</code> field</td><td>NIC name (e.g., <code>eno1</code>, <code>eth0</code>)</td></tr><tr><td><strong>XDP Mode</strong></td><td>Config file <code>xdp_mode</code> field</td><td><code>native</code>, <code>generic</code>, <code>skb</code>, or <code>auto</code></td></tr><tr><td><strong>Static Mit</strong></td><td>Config file <code>static.enabled</code></td><td><code>true</code> or <code>false</code></td></tr><tr><td><strong>Dynamic Mit</strong></td><td>Config file <code>dynamic.enabled</code></td><td><code>true</code> or <code>false</code></td></tr><tr><td><strong>Whitelist</strong></td><td>Config file <code>whitelist.enabled</code> + count of <code>whitelist.ips</code></td><td><code>true (N IPs)</code> or <code>false</code></td></tr><tr><td><strong>Config</strong></td><td>Config file existence at <code>/etc/openshield/openshield.yaml</code></td><td><code>PRESENT</code> or <code>MISSING</code> (red)</td></tr><tr><td><strong>BPF Pin</strong></td><td><code>bpf.LinkPinPath</code> — BPF link pin file</td><td><code>EXISTS</code> (green) or <code>MISSING</code> (red)</td></tr><tr><td><strong>Systemd</strong></td><td>Service file at <code>/etc/systemd/system/openshield-loader.service</code></td><td><code>INSTALLED</code> (green) or <code>NOT INSTALLED</code> (yellow)</td></tr></tbody></table><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Code</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:center;"><code>0</code></td><td>XDP program is loaded AND loader is running</td></tr><tr><td style="text-align:center;"><code>1</code></td><td>Not loaded or loader not running</td></tr></tbody></table><p>Scripts can check <code>$?</code> for automation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;OpenShield is running&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;OpenShield is not running&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><h2 id="color-output" tabindex="-1">Color output <a class="header-anchor" href="#color-output" aria-label="Permalink to &quot;Color output&quot;">​</a></h2><p>The command uses ANSI escape codes for color:</p><ul><li>🟢 Green (<code>\\033[32m</code>) — loaded, running, available, exists</li><li>🔴 Red (<code>\\033[31m</code>) — not loaded, unavailable, missing</li><li>🟡 Yellow (<code>\\033[33m</code>) — not running, not installed</li></ul><p>Color output is sent to stdout regardless of whether the output is a TTY. To strip colors:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s/\\x1b\\[[0-9;]*m//g&#39;</span></span></code></pre></div><h2 id="relation-to-tui-status-screen" tabindex="-1">Relation to TUI status screen <a class="header-anchor" href="#relation-to-tui-status-screen" aria-label="Permalink to &quot;Relation to TUI status screen&quot;">​</a></h2><p>The CLI <code>status</code> command shows a static snapshot. The TUI Status screen (key <code>6</code>) shows the same information plus:</p><ul><li>Real-time health badges (loader/xdp/telemetry/event pipe status)</li><li>Live statistics (total/passed/dropped, pass/drop rates)</li><li>Map utilization with progress bars</li><li>Drop path breakdown</li><li>Kernel version and system uptime</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p><a href="/pingless-studios-docs/openshield-xdp/cli/fix">Fix Reference</a> · <a href="/pingless-studios-docs/openshield-xdp/cli/load">Load Deep-Dive</a> · <a href="/pingless-studios-docs/openshield-xdp/cli/commands">CLI Commands</a></p>`,23)])])}const g=s(n,[["render",d]]);export{u as __pageData,g as default};
